private List<Map<String, Object>> messages(ModelRequest request) {
    var values = new ArrayList<Map<String, Object>>();
    var toolNames = new LinkedHashMap<String, String>();
    for (Message message : request.messages()) {
        if (message.role() == Message.Role.TOOL) {
            String toolCallId = message.toolCallId().orElseThrow();
            String toolName = toolNames.get(toolCallId);
            if (toolName == null) throw new IllegalArgumentException("tool result has no matching tool call");
            values.add(Map.of("role", "user", "parts", List.of(Map.of("functionResponse", Map.of(
                    "name", toolName, "response", Map.of("output", message.text()), "id", toolCallId)))));
        } else {
            var parts = new ArrayList<Map<String, Object>>();
            for (Content block : message.content()) {
                if (block instanceof Content.Text text) parts.add(Map.of("text", text.text()));
                else {
                    Content.ToolCall call = (Content.ToolCall) block;
                    toolNames.put(call.id(), call.name());
                    parts.add(Map.of("functionCall", Map.of("id", call.id(), "name", call.name(), "args", call.arguments())));
                }
            }
